# Generated by build.py from recipe.yml for recipe mqtt-change-retained-config-mid-test. Do not edit.
Set-Location $PSScriptRoot
$server0 = Start-Process surl -ArgumentList '--allow-anonymous', '--topic', '"devices/#;retain"', 'mqtt://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -s -d interval=60 mqtt://127.0.0.1:8080/devices/lamp/config --next -s mqtt://127.0.0.1:8080/devices/lamp/config --next -s -d interval=15 mqtt://127.0.0.1:8080/devices/lamp/config --next -s mqtt://127.0.0.1:8080/devices/lamp/config } finally { Stop-Process $server0 }
